window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6e30c2f5e6bb7488"]={"versions": [{"id": "FIG-6e30c2f5e6bb7488", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichten- und Bereitstellungsdiagramm (Deployment Diagram) für den Testaufbau des Communication Managements in der AUTOSAR Adaptive Platform. Dargestellt ist eine verteilte Testumgebung bestehend aus zwei Ziel-Steuergeräten (ECU1, ECU2) und einem CI/CD-Testknoten (Jenkins), aufgeteilt in Hardware-, Betriebssystem-, Middleware-/Bibliotheks- und Anwendungsschichten sowie deren physische und logische Kommunikationspfade.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System umfasst drei Knoten:</p>\n<ul class=\"fig-list\"><li><strong>ECU1</strong>: Hardwareknoten „Intel MinnowBoard“ mit Betriebssystem „Linux with Real-time Patches“. Darauf aufsetzend die Bibliotheksschicht „POXIS libs (libc, ...)“ sowie das SOME/IP-Binding „vSomeIP“. Auf Middleware-Ebene befindet sich „ARA“ (AUTOSAR Runtime for Adaptive Applications), darüber die Applikation „Video Data“.\n</li><li><strong>ECU2</strong>: Hardwareknoten „Renesas R-CAR H3 ULCB“ mit Betriebssystem „Linux with Real-time Patches“, Bibliotheksschicht „POXIS libs (libc, ...)“, „vSomeIP“ und der Middleware-Schicht „ARA“. Darüber läuft die Applikation „System Test Applications“.\n</li><li><strong>Jenkins</strong>: Hardwareknoten „PC“ mit Standard-„Linux“. Darauf läuft die Komponente „Jenkins“, welche die Testanwendung „CM Tester“ ansteuert.\n</li><li><strong>Schnittstellen &amp; Verbindungen</strong>: Gestrichelte rote Linien stellen Kommunikations- und Kontrollverbindungen dar. Physisch/netzwerkseitig sind die Steuergeräte und der PC untereinander vernetzt. Logische Pfade führen von den Hardware-/OS-Ebenen über Middleware/ARA in die jeweiligen Test- und Nutzapplikationen („Video Data“, „System Test Applications“, „CM Tester“).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Testinfrastruktur orchestriert über den PC bzw. Jenkins automatisierte Kommunikationstests zwischen ECU1 und ECU2:</p>\n<ul class=\"fig-list\"><li>Über die physikalischen Netzwerkverbindungen kommunizieren die Steuergeräte über SOME/IP („vSomeIP“) und ARA miteinander.\n</li><li>Die Applikation „Video Data“ auf ECU1 und die „System Test Applications“ auf ECU2 tauschen Test- und Nutzdaten über den ARA-Kommunikationsstack aus.\n</li><li>Der „CM Tester“ auf dem Jenkins-Host steuert und überwacht die Testausführung auf den Zielknoten über das zugrundeliegende Netzwerk.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Nicht-normatives Übersichtsschaubild eines Referenz- und HIL-Systemtestaufbaus für AUTOSAR Adaptive Platform Communication Management:</p>\n<ul class=\"fig-list\"><li>Zeigt eine heterogene Hardware-Zielplattform (x86_64 Intel MinnowBoard und ARM64 Renesas R-CAR H3 ULCB) unter Linux mit Echtzeit-Erweiterungen (PREEMPT_RT).\n</li><li>Die Middleware-Implementierung basiert auf dem SOME/IP-Stack (vSomeIP) und den standardisierten POSIX-Betriebssystem-Bibliotheken (im Diagramm als „POXIS libs“ typografisch fehlerhaft geführt).\n</li><li>Dient Integratoren und Testentwicklern als Blueprint für automatisierte System- und Integrationstests (CI/CD) mit Jenkins.\n</li></ul>"}, {"id": "FIG-36c2736895988589", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichten- und Bereitstellungsdiagramm (Deployment Diagram) für den Testaufbau des Communication Managements in der AUTOSAR Adaptive Platform. Dargestellt ist eine verteilte Testumgebung bestehend aus zwei Ziel-Steuergeräten (ECU1, ECU2) und einem CI/CD-Testknoten (Jenkins), aufgeteilt in Hardware-, Betriebssystem-, Middleware-/Bibliotheks- und Anwendungsschichten sowie deren physische und logische Kommunikationspfade.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System umfasst drei Knoten:</p>\n<ul class=\"fig-list\"><li><strong>ECU1</strong>: Hardwareknoten „Intel MinnowBoard“ mit Betriebssystem „Linux with Real-time Patches“. Darauf aufsetzend die Bibliotheksschicht „POSIX libs (libc, ...)“ sowie das SOME/IP-Binding „vSomeIP“. Auf Middleware-Ebene befindet sich „ARA“ (AUTOSAR Runtime for Adaptive Applications), darüber die Applikationsebene „CM Test Application(s)“.\n</li><li><strong>ECU2</strong>: Hardwareknoten „Renesas R-CAR H3 ULCB“ mit Betriebssystem „Linux with Real-time Patches“, Bibliotheksschicht „POSIX libs (libc, ...)“, „vSomeIP“ und der Middleware-Schicht „ARA“. Darüber läuft ebenfalls die Applikationsebene „CM Test Application(s)“.\n</li><li><strong>Jenkins</strong>: Hardwareknoten „PC“ mit Standard-„Linux“. Darauf läuft die Komponente „Jenkins“, welche die Testanwendung „CM Tester“ ansteuert.\n</li><li><strong>Schnittstellen &amp; Verbindungen</strong>: Gestrichelte rote Linien stellen Kommunikations- und Kontrollverbindungen dar. Physisch/netzwerkseitig sind die Steuergeräte und der PC untereinander vernetzt. Logische Pfade führen von den Hardware-/OS-Ebenen über Middleware/ARA in die jeweiligen Testapplikationen („CM Test Application(s)“ auf ECU1/ECU2 und „CM Tester“ auf dem Jenkins-Knoten).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Testinfrastruktur orchestriert über den PC bzw. Jenkins automatisierte Kommunikationstests zwischen ECU1 und ECU2:</p>\n<ul class=\"fig-list\"><li>Über die physikalischen Netzwerkverbindungen kommunizieren die Steuergeräte über SOME/IP („vSomeIP“) und ARA miteinander.\n</li><li>Die „CM Test Application(s)“ auf ECU1 und ECU2 tauschen Kommunikations- und Testdaten über den ARA-Kommunikationsstack aus.\n</li><li>Der „CM Tester“ auf dem Jenkins-Host steuert und überwacht die Testausführung auf den Zielknoten über das zugrundeliegende Netzwerk.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Nicht-normatives Übersichtsschaubild eines Referenz- und HIL-Systemtestaufbaus für AUTOSAR Adaptive Platform Communication Management:</p>\n<ul class=\"fig-list\"><li>Zeigt eine heterogene Hardware-Zielplattform (x86_64 Intel MinnowBoard und ARM64 Renesas R-CAR H3 ULCB) unter Linux mit Echtzeit-Erweiterungen (PREEMPT_RT).\n</li><li>Die Middleware-Implementierung basiert auf dem SOME/IP-Stack (vSomeIP) und den standardisierten POSIX-Betriebssystem-Bibliotheken („POSIX libs (libc, ...))“.\n</li><li>Dient Integratoren und Testentwicklern als Blueprint für automatisierte System- und Integrationstests (CI/CD) mit Jenkins zur Validierung der Kommunikationsmanagement-Anwendungen („CM Test Application(s)“).\n</li></ul>"}], "trans": [{"from": "FIG-6e30c2f5e6bb7488", "to": "FIG-36c2736895988589", "fr": "R19-03", "tr": "R19-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>ECU1, Anwendungsbox: Beschriftung von „Video Data“ in „CM Test Application(s)“ geändert.\n</li><li>ECU2, Anwendungsbox: Beschriftung von „System Test Applications“ in „CM Test Application(s)“ geändert.\n</li><li>ECU1 und ECU2, Bibliothekschicht: Schreibfehler korrigiert von „POXIS libs (libc, ...)“ zu „POSIX libs (libc, ...)“.\n</li></ul>"}]};
